import{_ as r,o,c as s,ag as n}from"./chunks/framework.DzGOF12C.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"맹자","slug":"맹자","link":"#맹자","children":[]},{"level":2,"title":"순자","slug":"순자","link":"#순자","children":[]},{"level":2,"title":"맹자 vs 순자 비교","slug":"맹자-vs-순자-비교","link":"#맹자-vs-순자-비교","children":[]}],"relativePath":"philosophy/China/02. 맹자와 순자.md","filePath":"philosophy/China/02. 맹자와 순자.md"}'),l={name:"philosophy/China/02. 맹자와 순자.md"};function e(a,t,g,i,d,h){return o(),s("div",null,[...t[0]||(t[0]=[n('<h2 id="맹자" tabindex="-1">맹자 <a class="header-anchor" href="#맹자" aria-label="Permalink to &quot;맹자&quot;">​</a></h2><p><strong>문제의식</strong>: 전국시대의 혼란한 상황을 해결하는 것.</p><p><strong>인자무적(仁者無敵), 왕도정치</strong>: 덕치 = 인치 = 왕도. 패도정치(힘으로 다스림) 대신 왕도정치(덕을 바탕으로 백성의 마음을 얻어 다스림)를 주장.</p><p><strong>성선설</strong>: 사람은 누구나 **불인인지심(不忍人之心)**을 가짐 — 타인의 고통이나 불행을 보고 차마 그대로 넘어가지 못하는 마음. (어린아이가 우물로 기어가는 모습을 본다면 누구라도 차마 넘어가지 못할 것이라는 예시)</p><ul><li><strong>사단(四端)</strong>: 측은지심, 수오지심, 사양지심, 시비지심이 각각 인·의·예·지의 단서(端緖)</li><li>이 사단이 바로 성선설의 근거</li></ul><p><strong>사람은 왜 타락하는가</strong></p><ol><li>시스템의 미비: 무항산(無恒産, 일정한 생업이 없음), 무항심(無恒心, 일정한 도덕심이 없음) — 먹고살 기반이 없으면 도덕심도 유지되기 어려움</li><li>수양의 부족: 본성을 잘 실행할 수 있도록 <strong>호연지기</strong>를 길러야 함</li></ol><p><strong>역성혁명</strong>: 왕이 왕답지 못하면 교체해야 한다는 주장. 공자의 <strong>정명론</strong>(&quot;군군신신부부자자&quot;)과 연결됨.</p><p><strong>올바름의 기준</strong>: 맹자는 올바름의 기준을 <strong>본성</strong>에서 찾음 — 인간의 본성이 선하기 때문. (반면 순자는 내면에서 기준을 찾을 수 없다고 봄 — 선의 가능성을 지니고 있지 않기 때문)</p><h2 id="순자" tabindex="-1">순자 <a class="header-anchor" href="#순자" aria-label="Permalink to &quot;순자&quot;">​</a></h2><p><strong>문제의식</strong>: 혼란스러운 사회 상황을, 인간을 도덕적 존재로 만들어 극복하려 함. 인간의 본성이 <strong>악하기</strong> 때문에 이를 <strong>예를 통해 교화</strong>해야 함 → <strong>예치(禮治) 정치</strong>, <strong>성악설</strong>.</p><p><strong>천인지분(天人之分)</strong>: 하늘은 아무런 의지 없는 자연법칙일 뿐 — 초월적 존재를 부정.</p><p><strong>예(禮)의 발생과 존재 이유</strong></p><ul><li>인간의 본성은 악하기 때문에 혼란이 생김 — 예의와 법도는 <strong>성인의 실천</strong>으로 만들어지는 것</li><li>자연 상태의 인간은 욕망추구적 존재인데, 욕망의 대상인 재화는 부족함 → 다툼이 일어나 공동체 붕괴로 이어짐</li><li>예의 본질은 <strong>구별·구분</strong> — 욕망과 그 대상이 균형을 이루도록, 신분에 따라 어울리는 대우와 욕망 실현 방식을 정해줌 (귀천과 나이에 따른 차등)</li><li>형벌이 죄에 합당하게 이뤄지면 권위가 서고, 그렇지 않으면 가벼이 여겨짐</li></ul><p><strong>군주</strong>: 예와 법을 잘 아는 자, 백성을 인간답게 만들어줄 수 있는 자. 선왕(옛 성왕)도 좋지만, 현재적 상황에 맞는 <strong>후왕</strong>을 강조. 국가를 부국하게 만드는 왕도뿐 아니라 패자(覇者)도 상대적으로 긍정.</p><h2 id="맹자-vs-순자-비교" tabindex="-1">맹자 vs 순자 비교 <a class="header-anchor" href="#맹자-vs-순자-비교" aria-label="Permalink to &quot;맹자 vs 순자 비교&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>맹자</th><th>순자</th></tr></thead><tbody><tr><td><strong>인성론</strong></td><td>성선설 (사단이 선천적으로 존재)</td><td>성악설 (선의 가능성 자체가 없음)</td></tr><tr><td><strong>기준의 소재</strong></td><td>본성(내면)에서 올바름의 기준을 찾음</td><td>내면에서 찾을 수 없어, 성인이 예를 제정해 기준을 세움</td></tr><tr><td><strong>정치 근본</strong></td><td>백성이 근본</td><td>군자가 백성의 근본</td></tr><tr><td><strong>다스림의 방법</strong></td><td>덕치 (내면의 선한 본성 확충)</td><td>예치 (외적 규범을 통한 교화)</td></tr></tbody></table>',17)])])}const c=r(l,[["render",e]]);export{_ as __pageData,c as default};
